import{_ as a,o as i,c as s,an as t}from"./chunks/framework.CcxR8fTC.js";const k=JSON.parse('{"title":"Exporting to RME Format","description":"","frontmatter":{},"headers":[],"relativePath":"usage/exporting_to_rme.md","filePath":"usage/exporting_to_rme.md","lastUpdated":null}'),o={name:"usage/exporting_to_rme.md"};function n(r,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="Exporting-to-RME-Format" tabindex="-1">Exporting to RME Format <a class="header-anchor" href="#Exporting-to-RME-Format" aria-label="Permalink to &quot;Exporting to RME Format {#Exporting-to-RME-Format}&quot;">​</a></h1><p>The <code>ADRIA.RMEExport.export_to_rme()</code> utility allows ADRIA <code>ResultSet</code> objects to be exported into a format compatible with <a href="https://github.com/open-AIMS/ReefModEngine.jl" target="_blank" rel="noreferrer">ReefModEngine.jl</a>. This is primarily used to link ADRIA ecological simulations with the <strong>CREAM (Comprehensive Reef Economic Analysis Model)</strong> suite via the <code>cost-eco-model-linker</code>.</p><h2 id="Domain-Compatibility" tabindex="-1">Domain Compatibility <a class="header-anchor" href="#Domain-Compatibility" aria-label="Permalink to &quot;Domain Compatibility {#Domain-Compatibility}&quot;">​</a></h2><p>The export targets <strong>Great Barrier Reef (GBR) domains</strong>. Both a standard ADRIA GBR <code>Domain</code> and an <code>RMEDomain</code> (<code>load_domain(RMEDomain, ...)</code>) are supported. It requires:</p><ul><li><p>A <code>GBRMPA_ID</code> column in the domain spatial data (<code>rs.loc_data</code>), used to name the yearly reefsets in <code>scenario_info.json</code>. Current ADRIA GBR DataPackages and current RME data packages both provide it. Older packages without <code>GBRMPA_ID</code>, and non-GBR or synthetic domains, are not supported.</p></li><li><p>The standard 5-group functional coral model and the standard seeding factors (<code>N_seed_*</code>, <code>seeding_devices_per_m2</code>). The evenness normalisation hard-codes 5 groups.</p></li><li><p>An <code>RCP</code> in the results that also exists in the domain&#39;s DHW data (needed for the GCM-name lookup).</p></li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Because ADRIA and RME use different internal standards, the export process performs several critical &quot;translation&quot; steps:</p><ol><li><p><strong>Unit Scaling</strong>: Proportions (0.0 - 1.0) are scaled to percentages (0 - 100) where required by the economic model.</p></li><li><p><strong>Coordinate Variables</strong>: NetCDF outputs include human-readable coordinate variables for <code>timesteps</code> (years) and <code>locations</code> (Unique Reef IDs).</p></li><li><p><strong>Intervention Realization</strong>: ADRIA&#39;s spatial intervention logs (<code>seed_log</code>) are translated into absolute coral counts and realized intervention areas (km²) for logistical cost calculations.</p></li></ol><h2 id="Usage-Workflow" tabindex="-1">Usage Workflow <a class="header-anchor" href="#Usage-Workflow" aria-label="Permalink to &quot;Usage Workflow {#Usage-Workflow}&quot;">​</a></h2><h3 id="1.-Generate-Paired-Scenarios" tabindex="-1">1. Generate Paired Scenarios <a class="header-anchor" href="#1.-Generate-Paired-Scenarios" aria-label="Permalink to &quot;1. Generate Paired Scenarios {#1.-Generate-Paired-Scenarios}&quot;">​</a></h3><p>The economic model calculates benefits by comparing an intervention to its corresponding counterfactual. Use <code>sample_pairwise()</code> to ensure your scenario set contains the necessary pairs in the correct order.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADRIA</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Standard ADRIA GBR domain</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dom </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADRIA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">load_domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;path/to/domain&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;45&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ...or an RME data package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dom </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADRIA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">load_domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(RMEDomain, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;path/to/rme_data_package&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;45&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate 16 paired scenarios (16 Counterfactuals + 16 matching Interventions)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scens </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADRIA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sample_pairwise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dom, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="2.-Run-Simulations" tabindex="-1">2. Run Simulations <a class="header-anchor" href="#2.-Run-Simulations" aria-label="Permalink to &quot;2. Run Simulations {#2.-Run-Simulations}&quot;">​</a></h3><p>Run the scenarios normally. Ensure you are using a domain compatible with the Great Barrier Reef (GBR) if you intend to use the standard CREAM cost models.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADRIA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">run_scenarios</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dom, scens, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;45&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="3.-Export-Results" tabindex="-1">3. Export Results <a class="header-anchor" href="#3.-Export-Results" aria-label="Permalink to &quot;3. Export Results {#3.-Export-Results}&quot;">​</a></h3><p>Call <code>export_to_rme()</code> to generate the RME-compatible directory structure.</p><p><code>export_to_rme()</code> takes the <code>Domain</code> used to run the scenarios, the <code>ResultSet</code>, and the output directory.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADRIA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RMEExport</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">out_dir </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;./economic_analysis_input&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">export_to_rme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dom, rs, out_dir)</span></span></code></pre></div><p>Optional keyword arguments: <code>map_counterfactuals</code>, <code>pdp_geopackage_path</code>, <code>scen_spec</code>.</p><h2 id="Exported-Files" tabindex="-1">Exported Files <a class="header-anchor" href="#Exported-Files" aria-label="Permalink to &quot;Exported Files {#Exported-Files}&quot;">​</a></h2><p>The utility produces the following files in the target directory:</p><ul><li><p><strong><code>results.nc</code></strong>: NetCDF containing <code>total_cover</code>, <code>relative_juveniles</code>, <code>relative_shelter_volume</code> (also written as <code>relative</code>), <code>evenness</code>, and zero-filled <code>rubble</code> / <code>cots</code> placeholders, plus <code>timesteps</code> / <code>locations</code> / <code>scenarios</code> coordinate variables.</p></li><li><p><strong><code>iv_yearly_scenarios.csv</code></strong>: A year-by-year log of absolute coral counts, seeding densities, and deployment areas per scenario.</p></li><li><p><strong><code>scenario_info.json</code></strong>: Metadata mapping scenario indices to counterfactual status and defining the unique &quot;reefsets&quot; used each year.</p></li><li><p><strong><code>reef_information.csv</code></strong>: Spatial metadata for the reefs involved in the simulation.</p></li></ul><h2 id="Technical-Notes" tabindex="-1">Technical Notes <a class="header-anchor" href="#Technical-Notes" aria-label="Permalink to &quot;Technical Notes {#Technical-Notes}&quot;">​</a></h2><h3 id="Shelter-Volume-Scaling" tabindex="-1">Shelter Volume Scaling <a class="header-anchor" href="#Shelter-Volume-Scaling" aria-label="Permalink to &quot;Shelter Volume Scaling {#Shelter-Volume-Scaling}&quot;">​</a></h3><p>The downstream economic model applies a <strong>9.33x scaling factor</strong> to the exported <code>relative_shelter_volume</code>. This reconciles ADRIA&#39;s reference standard (relative to 1 m²) with the historical GBR standard (relative to a 95cm diameter circle).</p><h3 id="Counterfactual-Detection" tabindex="-1">Counterfactual Detection <a class="header-anchor" href="#Counterfactual-Detection" aria-label="Permalink to &quot;Counterfactual Detection {#Counterfactual-Detection}&quot;">​</a></h3><p>A scenario is flagged as a <code>counterfactual</code> in the export if all intervention factors (<code>N_seed</code>, <code>fogging</code>, <code>SRM</code>, etc.) are set to zero. This bitmask is stored in <code>scenario_info.json</code>.</p>`,28)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
